const staleCandidates = `-- name: StaleCandidates :many
SELECT employee_id FROM payroll_input_changes
WHERE period_id = $1 AND changed_at > $2
ORDER BY employee_id
`

type StaleCandidatesParams struct {
	PeriodID      uuid.UUID
	CalcStartedAt time.Time
}

// O12: karyawan dengan perubahan input setelah kalkulasi mulai membaca (changed_at > calc_started_at).
func (q *Queries) StaleCandidates(ctx context.Context, arg StaleCandidatesParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, staleCandidates, arg.PeriodID, arg.CalcStartedAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var employee_id uuid.UUID
		if err := rows.Scan(&employee_id); err != nil {
			return nil, err
		}
		items = append(items, employee_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const startCalculation = `-- name: StartCalculation :one
UPDATE payroll_runs
SET status = 'CALCULATING', calc_version = calc_version + 1, chunks_total = 0, chunks_done = 0,
    eligible_count = NULL, input_fingerprint = NULL, total_gross = NULL, total_deductions = NULL, total_net = NULL,
    item_ok_count = NULL, item_error_count = NULL, item_excluded_count = NULL, warning_count = NULL,
    failure_reason = NULL, calculated_at = NULL, calc_started_at = clock_timestamp()
WHERE id = $1 AND status IN ('DRAFT', 'CALCULATED', 'FAILED')
RETURNING calc_version
`

// [3] guard status: hanya DRAFT/CALCULATED/FAILED → CALCULATING (CALCULATING ditolak, Step 3 `08`).
// calc_started_at = clock_timestamp() SAMBIL memegang periode FOR UPDATE (batas bawah stale O12).
func (q *Queries) StartCalculation(ctx context.Context, id uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, startCalculation, id)
	var calc_version int32
	err := row.Scan(&calc_version)
	return calc_version, err
}

